package com.deutschai.app

/**
 * Additional B1/B2 thematic sentence courses.
 *
 * Each topic starts from five reusable, level-appropriate subordinate clauses.
 * Five different sentence frames create 25 distinct Czech-to-German prompts.
 * Keeping the clauses as explicit data makes the vocabulary easy to mine later
 * for the shared vocabulary drill without duplicating the source sentences.
 */
private fun additionalLevelSentenceCourse(
    level: String,
    id: String,
    title: String,
    subtitle: String,
    vararg rows: String
): SentenceCourseDefinition = SentenceCourseDefinition(
    id = id,
    title = title,
    subtitle = subtitle,
    level = level,
    items = rows.map { row ->
        val fields = row.split("§", limit = 3)
        require(fields.size == 3) { "Invalid thematic sentence-course row: $row" }
        SentencePracticeItem(fields[0], fields[1], fields[2])
    }
    ,
    additionalLevelSentenceCourse("B2", "b2_industry_automation", "Průmysl, automatizace a výrobní procesy", "Hovořit o digitalizaci výroby, efektivitě, údržbě a technických změnách",
        "automatisierte Anlagen Produktionsabläufe präziser und effizienter gestalten§automatizovaná zařízení umožňují řídit výrobní procesy přesněji a efektivněji",
        "ungeplante Stillstände erhebliche wirtschaftliche Folgen verursachen§neplánované odstávky mohou způsobit značné ekonomické důsledky",
        "vorausschauende Wartung technische Ausfälle frühzeitig erkennen kann§prediktivní údržba může včas odhalit technické poruchy",
        "die Einführung neuer Technologien sorgfältig vorbereitet werden muss§zavedení nových technologií musí být pečlivě připraveno",
        "qualifizierte Fachkräfte für die Bedienung komplexer Systeme unverzichtbar bleiben§kvalifikovaní odborníci zůstávají nezbytní pro obsluhu komplexních systémů"
    )
    ,
    additionalLevelSentenceCourse("B1", "b1_insurance", "Pojištění a ochrana při nečekaných událostech", "Vysvětlit pojistnou událost, rozsah krytí a potřebné doklady",
        "eine Versicherung bestimmte Schäden nur unter festgelegten Bedingungen übernimmt§pojišťovna hradí určité škody pouze za stanovených podmínek",
        "man einen Schaden möglichst schnell bei der Versicherung melden sollte§člověk by měl škodu nahlásit pojišťovně co nejrychleji",
        "die Höhe der Selbstbeteiligung im Vertrag genau angegeben ist§výše spoluúčasti je přesně uvedena ve smlouvě",
        "Fotos und Belege die Bearbeitung eines Schadensfalls erleichtern können§fotografie a doklady mohou usnadnit vyřízení pojistné události",
        "nicht jeder Schaden automatisch durch die Versicherung gedeckt ist§ne každá škoda je automaticky kryta pojištěním"
    )
)

